from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, expire_time]
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                val, expire_time = cache[key]
                if expire_time > t:
                    # present, update
                    cache[key] = [value, t + ttl]
                    cache.move_to_end(key)
                else:
                    # expired, remove first
                    del cache[key]
                    if len(cache) >= capacity:
                        cache.popitem(last=False)
                    cache[key] = [value, t + ttl]
                    cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = [value, t + ttl]
                cache.move_to_end(key)
        elif op[0] == 'get':
            _, t, key = op
            if key in cache:
                val, expire_time = cache[key]
                if expire_time > t:
                    results.append(val)
                    cache.move_to_end(key)
                else:
                    del cache[key]
                    results.append(-1)
            else:
                results.append(-1)
    return results

